#include <iostream>

const int limite{5};

int precio_total(int articulos) {
    return articulos * limite;
}

bool alcanza_minimo(int articulos) {
    return articulos >= limite;
}

bool comprobar(int articulos, int total_esperado, bool minimo_esperado) {
    const int total{precio_total(articulos)};
    const bool alcanza{alcanza_minimo(articulos)};
    const bool coincide{total == total_esperado && alcanza == minimo_esperado};
    std::cout << "articulos=" << articulos << " total=" << total
              << " expected=" << total_esperado << " minimum=" << alcanza
              << " expected_minimum=" << minimo_esperado << " ";
    if (coincide) { std::cout << "OK\n"; }
    else { std::cout << "FAIL\n"; }
    return coincide;
}

int main() {
    bool correcto{true};
    if (!comprobar(0, 0, false)) { correcto = false; }
    if (!comprobar(4, 20, false)) { correcto = false; }
    if (!comprobar(5, 25, true)) { correcto = false; }
    if (!comprobar(6, 30, true)) { correcto = false; }
    if (!comprobar(10, 50, true)) { correcto = false; }
    if (!correcto) { std::cout << "Suite: FAIL\n"; return 1; }
    std::cout << "Suite: OK\n";
    return 0;
}

